statement.sql:
SELECT DISTINCT u.UserId as Id , UserName , FirstName , LastName , MiddleName , CASE WHEN len(isnull(middlename, '')) = 0 THEN isnull(LastName, '') + ', ' + isnull(FirstName, '') ELSE isnull(LastName, '') + ', ' + isnull(FirstName, '') + ' ' + middlename END AS FullName , NamePrefix as Title , u.UserTypeCode , lUt.ShortDisplayValue AS UserType , ar.roleName AS DefaultRole , (SELECT TOP 1 ca.ContactAddress FROM ContactAddresses ca WHERE p.PersonId = ca.EntityId AND ca.EntityTypeCode = 1 AND ca.ContactAddressTypeCode = 1
AND ca.IsPreferred = 1
AND ca.ContactAddressPurposeCode = 1
) PrimaryEmail , (SELECT TOP 1 ca.ContactAddress FROM ContactAddresses ca WHERE p.PersonId = ca.EntityId AND ca.EntityTypeCode = 1 AND ca.ContactAddressTypeCode = 2
AND ca.IsPreferred = 1
AND ca.ContactAddressPurposeCode = 1
) PrimaryPhone FROM ac_user u INNER JOIN people p ON u.userid = p.userid INNER JOIN ac_role ar ON ar.roleid = u.defaultRoleid INNER JOIN lookupUserType lUt ON lut.lookupcode = u.usertypecode WHERE u.UserId IN (SELECT UserId FROM AC_Permission(NOLOCK)
Status = 'Granted' getdate() BETWEEN isnull(StartDateTime, getdate() - 1) AND isnull(EndDateTime, getdate() + 1)
)
